/**
 * Headline font for the print edition: Anek Devanagari at 87.5% width, as
 * static (non-variable) instances, subset to Devanagari + Latin with all
 * shaping kept. Chrome embeds variable-font instances as Type 3 glyphs; these
 * embed as normal Type 0 fonts.
 *
 * Made with fontTools (varLib.instancer + subset) from the Google Fonts
 * variable font. Licence: SIL Open Font License 1.1, see fonts/OFL-AnekDevanagari.txt.
 */

const ANEK_700 = "";
const ANEK_800 = "";

export const PRINT_FONT_FACES = `
@font-face { font-family: "Anek Print"; font-weight: 700; src: url(data:font/woff2;base64,${ANEK_700}) format("woff2"); }
@font-face { font-family: "Anek Print"; font-weight: 800; src: url(data:font/woff2;base64,${ANEK_800}) format("woff2"); }
`;
